"""HR, behavioural, communication and managerial questions, plus resume-interview templates.

Model answers here are *guidance*: structure and what a strong answer contains. Students must use their
own real experience; the platform never supplies fabricated achievements.
"""

from .catalog import text

H, C, M = "hr", "communication", "managerial"
STAR = "STAR"
OWN = " Use your own real example."

HR = [
    # ── Core HR ──────────────────────────────────────────────────────────────
    text(H, "hr-core", "easy", "Tell me about yourself.",
         "Keep it to about 60–90 seconds in a present → past → future order: who you are now (course, year, focus area), the most relevant skills and projects that brought you here, and what role you are aiming for and why. Avoid reciting your whole résumé or personal details unrelated to the job.",
         [["student", "studying", "degree", "graduat", "engineer"], ["project", "internship", "built", "skill"], ["interested", "looking", "goal", "role", "opportunity"]],
         ["Which of those projects are you most proud of?"], "foundational", mistakes="Reading the résumé aloud, speaking for several minutes, or sharing family/personal details."),
    text(H, "hr-core", "medium", "Why should we hire you?",
         "Connect two or three of your genuine strengths to what the role needs: relevant skills (give a concrete example or project), eagerness and speed in learning, and reliability. Be specific and confident without exaggerating or putting down other candidates.",
         [["skill", "strength", "experience", "project"], ["role", "company", "team", "need", "requirement"], ["learn", "contribute", "value", "reliab"]],
         ["What would you do in your first 90 days?"], "foundational"),
    text(H, "hr-core", "medium", "Why do you want this role and this company?",
         "Show you researched the company: its product, domain or values. Link them to your interests and skills, and explain what you hope to learn and contribute. Avoid answers that are only about salary or location.",
         [["research", "product", "company", "domain", "values", "mission"], ["interest", "passion", "skill"], ["learn", "contribute", "grow"]],
         label="foundational"),
    text(H, "hr-core", "medium", "What are your strengths and weaknesses?",
         "Choose 2 strengths that are relevant to the role and prove each with a brief real example. For the weakness, name a genuine, non-critical one, explain what you are doing to improve it, and show progress. Avoid disguised strengths such as 'I work too hard' or claiming to have none.",
         [["strength"], ["weakness", "improv", "working on"], ["example", "for instance", "when i", "project"]],
         ["What have you done recently to improve that weakness?"], "foundational", mistakes="Fake weaknesses, or a weakness that is critical to the role."),
    text(H, "hr-core", "medium", "What motivates you, and where do you see yourself in five years?",
         "Describe real motivators, such as solving problems, learning, ownership or helping users, with an example. For career goals, be realistic: growing technical depth, taking on more responsibility, mentoring others. Show the goal fits with growing at this company.",
         [["motivat", "enjoy", "drive"], ["learn", "grow", "skill", "responsib"], ["goal", "five years", "future", "senior"]],
         label="foundational"),
    text(H, "hr-core", "medium", "How do you handle pressure and tight deadlines?",
         "Describe a concrete method: break work into priorities, estimate, communicate early about risks, focus on the highest-value tasks first, and ask for help when needed. Support it with a real example such as an exam week or project deadline and its outcome.",
         [["prioriti", "plan", "break", "schedule"], ["communicat", "inform", "ask", "help"], ["deadline", "example", "project"], ["calm", "focus", "manage"]],
         label="commonly tested"),
    text(H, "hr-core", "medium", "Is there a gap or difficulty in your academic or career journey? Please explain.",
         "Be honest and brief. State the fact plainly, explain what happened without blaming others, and focus on what you did during or after that time (learning, projects, certifications) and what you learned. Never invent a reason or hide it.",
         [["honest", "because", "reason", "happened"], ["learn", "learned", "course", "project", "improv"], ["now", "since", "moved forward", "ready"]],
         label="fresher-specific", mistakes="Lying, over-explaining, or blaming others."),
    text(H, "hr-core", "easy", "Do you have any questions for us?",
         "Always ask 2–3 thoughtful questions: what a typical first project looks like, how the team mentors new joiners, how success is measured in the first six months, or what the tech stack and learning opportunities are. Avoid asking only about salary and leave, and do not say you have no questions.",
         [["team", "mentor", "onboard", "training"], ["project", "stack", "technology", "work"], ["success", "expect", "growth", "learning"]],
         label="foundational"),
    # ── Behavioural (STAR) ───────────────────────────────────────────────────
    text(H, "behavioural", "medium", "Describe a challenging situation you faced and how you handled it." + OWN,
         "Use STAR: Situation (briefly set the scene), Task (your responsibility), Action (specific steps YOU took), Result (measurable outcome and what you learned). Spend most of the time on action and result.",
         [["situation", "when", "context"], ["task", "responsib", "goal"], ["i ", "action", "decided", "implemented"], ["result", "outcome", "learned", "improved"]],
         ["What would you do differently now?"], "foundational", STAR),
    text(H, "behavioural", "medium", "Tell me about a time you failed and what you learned." + OWN,
         "Pick a real failure of moderate stakes. Explain what happened and your part in it without blaming others, what you changed afterwards and how you applied it later. Interviewers look for accountability and growth.",
         [["failed", "mistake", "didn't work", "did not work", "went wrong"], ["responsib", "my part", "i should"], ["learn", "changed", "next time", "afterwards"], ["result", "improv"]],
         label="foundational", framework=STAR),
    text(H, "behavioural", "medium", "How do you handle feedback or criticism? Share an example." + OWN,
         "Say that you listen without being defensive, ask clarifying questions, and act on it. Then give a real instance: the feedback received, what you changed, and the improvement that followed.",
         [["listen", "understand", "clarif"], ["feedback", "criticism"], ["changed", "improv", "applied", "acted"], ["example", "when", "once"]],
         label="foundational", framework=STAR),
    text(H, "behavioural", "hard", "Tell me about a time you had to learn something new quickly." + OWN,
         "Describe the deadline or need, how you broke down what to learn, resources you used (docs, courses, mentors), how you applied it quickly, and the result. It shows adaptability.",
         [["deadline", "need", "situation", "required"], ["learn", "course", "documentation", "tutorial", "mentor"], ["applied", "built", "used", "implemented"], ["result", "outcome", "completed"]],
         label="commonly tested", framework=STAR),
    # ── Situational ──────────────────────────────────────────────────────────
    text(H, "situational", "medium", "You are assigned a task with unclear requirements and your manager is unavailable. What do you do?",
         "Clarify what you can from existing documents and similar work, list your assumptions and open questions, and send them in writing to the manager or the team. Begin with the parts that are clear while waiting, make the work easy to adjust, and confirm assumptions before finishing. Avoid either stalling silently or guessing and delivering something unreviewed.",
         [["clarif", "question", "ask"], ["assum", "document", "write", "email", "message"], ["start", "progress", "meanwhile", "clear part"], ["confirm", "review", "feedback"]],
         label="scenario-based"),
    text(H, "situational", "medium", "You realise you will miss a deadline. How do you handle it?",
         "Raise it as early as possible, explain the cause honestly and what is at risk, propose options (reduce scope, extra help, new date) with a recovery plan, and then deliver on it. Hiding the delay is the worst option.",
         [["early", "immediately", "inform", "communicat", "tell"], ["reason", "honest", "cause"], ["option", "plan", "scope", "help", "new date"], ["deliver", "follow", "update"]],
         label="scenario-based"),
    # ── Ethics ───────────────────────────────────────────────────────────────
    text(H, "ethics", "hard", "You notice a teammate copied code from a restricted source into the project. What do you do?",
         "Talk privately to the teammate first, since it may be a mistake, explain the licensing or confidentiality risk, and ask them to fix it. If it isn't resolved or the risk is serious, escalate to the manager or the appropriate channel. Stay factual, protect the team and the company, and never ignore it.",
         [["privately", "talk", "discuss", "speak"], ["risk", "licen", "confidential", "legal"], ["escalat", "manager", "report"], ["fact", "fair", "document"]],
         label="scenario-based"),
    text(H, "ethics", "hard", "Your manager asks you to report a number you believe is inaccurate to a client. What do you do?",
         "Raise your concern respectfully with evidence, ask how the number was derived, and offer to verify or present it with accurate caveats. Do not knowingly mislead a client; if the pressure continues, escalate through the proper channel or compliance.",
         [["concern", "raise", "respect"], ["evidence", "verify", "check", "data"], ["accurate", "honest", "transparen", "mislead"], ["escalat", "compliance", "channel"]],
         label="scenario-based"),
    # ── Teamwork / conflict ──────────────────────────────────────────────────
    text(H, "teamwork-conflict", "medium", "How do you resolve a disagreement with a teammate?",
         "Listen first to understand their reasoning, focus on the problem and shared goal rather than people, use data or a small experiment to compare options, compromise where it makes sense, and involve a lead only if it stays unresolved. Afterwards, keep the relationship positive.",
         [["listen", "understand"], ["goal", "problem", "shared", "objective"], ["data", "evidence", "experiment", "compromise"], ["escalat", "lead", "manager", "relationship"]],
         ["Describe a real disagreement and how it ended."], "foundational", STAR),
    text(H, "teamwork-conflict", "medium", "Describe your role in a team project and how you ensured the team succeeded." + OWN,
         "State the team size and your specific role, how work was split and tracked, how you communicated and helped teammates, a difficulty you overcame together, and the result. Say 'I' for your own actions and 'we' for team outcomes, and don't claim others' work.",
         [["team", "we"], ["role", "responsib", "my part", "i "], ["communicat", "track", "meeting", "git", "tool"], ["result", "outcome", "delivered", "completed"]],
         label="foundational", framework=STAR),
    # ── Fresher ──────────────────────────────────────────────────────────────
    text(H, "fresher", "easy", "You have no work experience. Why should we trust you with real responsibility?",
         "Acknowledge it honestly, then demonstrate readiness through evidence: academic and personal projects, internships or certifications, how quickly you learn, and your approach to ownership. Offer a specific example, show curiosity and willingness to be mentored.",
         [["project", "internship", "certif", "evidence", "built"], ["learn", "quick", "mentor", "curious"], ["responsib", "ownership", "commit", "reliab"]],
         label="fresher-specific"),
    text(H, "fresher", "medium", "Are you willing to relocate or work in shifts, and why or why not?",
         "Answer honestly about your actual constraints and flexibility. If you are flexible, say why it fits your goals; if you have limits, state them clearly and politely and offer alternatives. Never promise what you cannot do.",
         [["willing", "flexib", "open to", "comfortable"], ["because", "reason", "goal", "learn"], ["constraint", "prefer", "depend", "alternative"]],
         label="fresher-specific"),
]

COMMUNICATION = [
    text(C, "self-introduction", "easy", "Introduce yourself in 60–90 seconds as you would in a campus interview.",
         "Structure: greeting and name; present (course, college, focus); two or three relevant skills and one project; goal. Speak at a natural pace, simple sentences, and end with what you are looking for.",
         [["name", "i am", "my name"], ["student", "studying", "degree", "college", "engineer"], ["project", "skill", "built"], ["looking", "goal", "interested", "role"]],
         label="foundational"),
    text(C, "explain-simply", "medium", "Explain what an API is to a non-technical person in 4–5 sentences.",
         "Use an everyday analogy, such as a waiter taking your order to the kitchen and bringing back food: the API is the messenger that lets one piece of software ask another for something and get a response, without needing to know how it works inside. Avoid jargon, and finish with a real example (a weather app requesting data).",
         [["messenger", "waiter", "bridge", "connect", "analogy", "like a"], ["request", "ask"], ["response", "return", "result", "get back"], ["example", "weather", "app"]],
         label="foundational"),
    text(C, "explain-simply", "medium", "Explain the difference between a database and a spreadsheet to a manager.",
         "A spreadsheet is good for small, single-user analysis. A database stores large amounts of structured data reliably, supports many users at once, enforces rules and relationships, and can be queried fast. Use a business example, like customer orders.",
         [["spreadsheet", "excel"], ["database"], ["many users", "multiple users", "concurrent", "large"], ["rules", "relationship", "reliab", "secure"], ["example", "customer", "order"]]),
    text(C, "explain-project", "medium", "Explain your best project in 2 minutes to an interviewer who is not familiar with your domain." + OWN,
         "Cover: the problem and who it helps, your solution in plain language, your personal contribution and the tech used, one challenge and how you solved it, and the result or what you learned. Use specifics; avoid listing technologies without purpose.",
         [["problem", "goal", "purpose"], ["solution", "built", "developed", "implemented"], ["i ", "my role", "contribution"], ["challenge", "difficult", "issue"], ["result", "outcome", "learned"]],
         label="foundational"),
    text(C, "workplace", "medium", "Write a short, professional message to your lead explaining that you need an extra day to finish a task.",
         "State the situation and the new timeline directly and politely: what is done, what remains, why you need the extra day, and when you will deliver. Keep it concise, take responsibility, and offer to share progress. E.g. 'Hi [Name], the API integration is 80% complete. I need until tomorrow afternoon to finish testing. I will share an update at 3 PM. Thanks for understanding.'",
         [["hi", "hello", "dear"], ["extra day", "tomorrow", "deadline", "new date", "by"], ["complete", "done", "progress", "remain"], ["thank", "understand", "update"]],
         label="foundational"),
    text(C, "difficult-questions", "hard", "An interviewer says: 'Your marks are below average. Why should we shortlist you?' Respond professionally.",
         "Stay calm and accept the fact without defensiveness. Briefly explain context if relevant, then pivot to evidence of your ability: projects, skills, improvement trend and what you've done to prove practical competence. Finish positively with willingness to be evaluated through a test or task.",
         [["understand", "agree", "acknowledge", "true"], ["project", "skill", "practical", "built", "learn"], ["improv", "trend", "progress"], ["test", "task", "evaluate", "prove"]],
         label="scenario-based"),
    text(C, "group-discussion", "medium", "Group discussion topic: 'AI will create more jobs than it replaces.' Give a 60-second opening statement.",
         "Open with a clear stance and one definition, give two balanced reasons with an example each (e.g. new roles such as data and ML engineers; automation of repetitive tasks), acknowledge the counterpoint, and close with a constructive conclusion on reskilling. Avoid interrupting others and keep it concise.",
         [["i believe", "my view", "stance", "in my opinion"], ["job", "role", "employment"], ["example", "for instance"], ["however", "but", "counter", "on the other hand"], ["reskill", "learn", "conclusion", "therefore"]]),
    text(C, "presentation", "medium", "You have two minutes to present a technical topic of your choice to your class. Write the outline you would speak from.",
         "Opening hook and topic statement; three key points in a logical order with one example each; a quick demo or visual if possible; a closing summary and a call for questions. Prepare for timing and avoid putting paragraphs on slides.",
         [["opening", "introduc", "hook"], ["point", "key"], ["example", "demo", "visual"], ["summary", "conclusion", "question"]]),
    text(C, "strengths-weaknesses", "medium", "Describe one genuine strength and one genuine weakness of yours, with a short example of each." + OWN,
         "Name each clearly, back the strength with evidence from a real situation, and for the weakness describe concrete steps and progress. Keep it honest and specific.",
         [["strength"], ["weakness"], ["example", "when", "once", "project"], ["improv", "working on", "practis", "learn"]]),
]

MANAGERIAL = [
    text(M, "ownership", "medium", "Tell me about a project where you took ownership beyond your assigned tasks." + OWN,
         "Describe what you noticed (a gap, risk or opportunity), why you decided to act, what you did, how you kept others informed, and the measurable result. Make clear it was your initiative, and be honest about the scope.",
         [["noticed", "saw", "gap", "problem", "risk"], ["took", "initiative", "ownership", "decided"], ["team", "informed", "communicat", "stakeholder"], ["result", "outcome", "impact"]],
         label="scenario-based", framework=STAR),
    text(M, "ownership", "hard", "A bug you introduced reached production. What do you do?",
         "Immediately tell the team, help contain the impact (rollback or hotfix), find the root cause, fix it with a regression test, and communicate clearly with stakeholders. Afterwards run a blameless review and add safeguards such as tests, reviews or monitoring. Own the mistake without blaming others.",
         [["inform", "tell", "communicat", "immediately"], ["rollback", "hotfix", "contain", "fix"], ["root cause"], ["test", "monitor", "safeguard", "prevent"], ["responsib", "own", "blameless"]],
         label="scenario-based"),
    text(M, "decisions", "medium", "You must choose between building a feature quickly with technical debt, or taking longer to do it properly. How do you decide?",
         "Weigh business urgency, risk, cost of change later and the expected life of the feature. A quick version may suit a prototype or time-critical release if debt is documented and scheduled to be repaid; core or long-lived systems justify more care. Discuss the trade-off with stakeholders and record the decision.",
         [["trade-off", "tradeoff", "weigh", "balance"], ["debt"], ["urgen", "deadline", "business"], ["risk", "long-lived", "maintain"], ["stakeholder", "discuss", "document"]],
         label="scenario-based"),
    text(M, "decisions", "medium", "Why would you choose PostgreSQL over MongoDB for a college placement portal?",
         "The portal's data (students, companies, drives, applications) is structured and relational, needs integrity constraints, joins for reporting, and transactions for applications. PostgreSQL handles this well. MongoDB would suit flexible, document-heavy data, which is not the main need. State your assumptions about requirements.",
         [["relational", "structured", "relationship"], ["join", "report", "query"], ["transaction", "integrity", "constraint", "acid"], ["assum", "requirement"]],
         label="role-specific"),
    text(M, "system-design", "medium", "Design a simple URL shortener at a level suitable for a fresher. What are the main components and challenges?",
         "Clarify requirements first (create short links, redirect, maybe expiry). Components: an API to create and redirect, a database mapping short codes to long URLs (indexed on code), and a code generator (base62 of an id or random string with collision checks). Reads dominate, so add caching for popular links. Discuss validation, rate limiting, and scaling with replicas.",
         [["requirement", "clarif"], ["database", "store", "mapping"], ["unique", "base62", "hash", "generator", "collision"], ["cache", "redirect"], ["scal", "rate limit"]],
         ["How would you handle millions of redirects per day?"], label="role-specific"),
    text(M, "system-design", "hard", "How would you design a notification service that sends email and SMS to students reliably?",
         "Accept requests through an API and put them on a queue, so the API responds quickly. Workers consume the queue and call providers, with retries and exponential backoff, idempotency keys to avoid duplicates, and a dead-letter queue for failures. Store status for tracking, respect user preferences and rate limits, and monitor delivery rates.",
         [["queue"], ["worker", "async"], ["retry", "backoff"], ["idempot", "duplicate"], ["monitor", "status", "dead-letter", "track"]],
         label="advanced"),
    text(M, "adaptability", "medium", "How do you keep your skills current, and what have you taught yourself recently?" + OWN,
         "Describe an actual routine (documentation, courses, projects, reading code, communities), one specific thing you learned recently, how you applied it, and what you plan to learn next. Specific evidence beats general statements like 'I am a fast learner'.",
         [["learn", "course", "documentation", "tutorial", "read"], ["project", "built", "applied", "practic"], ["recent", "last", "week", "month"], ["next", "plan", "goal"]],
         label="foundational"),
]

# Templates for the Resume & Project interview. {placeholders} are filled ONLY from the student's own
# (editable) project / skill / education data; nothing is invented.
RESUME_PROJECT_TEMPLATES = [
    ("project", "medium", "Explain the architecture of your project \"{project}\". What are the main components and how do they interact?"),
    ("project", "medium", "In \"{project}\", what was YOUR personal contribution, as opposed to the team's?"),
    ("project", "medium", "Why did you choose the technologies you used in \"{project}\"? What alternatives did you consider?"),
    ("project", "hard", "What was the hardest technical challenge in \"{project}\" and how did you solve it?"),
    ("project", "medium", "How did you test \"{project}\", and how would you know if it broke?"),
    ("project", "hard", "What happens in \"{project}\" when an external API or the database fails? How would you make it more resilient?"),
    ("project", "hard", "If \"{project}\" had 100 times more users, what would break first and how would you scale it?"),
    ("project", "medium", "What would you improve in \"{project}\" if you had two more weeks?"),
    ("skill", "medium", "You listed {skill} as a skill. Describe a specific place where you used it and what you learned."),
    ("skill", "medium", "Explain one important concept in {skill} as if teaching a classmate, and where you applied it."),
    ("education", "easy", "How is your {degree} coursework relevant to the role you're targeting?"),
]
